    """
    Add a boolean field 'outlier' to every record in `records`.

    A record is an outlier when:
      |value - median| > 3 * scale

    where:
      - median is the batch median of the 'value' field
      - scale is the median absolute deviation (MAD) of the batch;
        if MAD == 0, fall back to the population standard deviation of the batch

    If the batch spread is degenerate (cannot compute finite numeric median
    or scale), no records are marked as outliers (all get outlier = False).

    The function modifies records in-place and also returns the records list.
    """
    import math

    # Helper: compute median of a non-empty list of numbers
    def _median(nums):
        n = len(nums)
        if n == 0:
            raise ValueError("median of empty list")
        s = sorted(nums)
        mid = n // 2
        if n % 2 == 1:
            return s[mid]
        else:
            return (s[mid - 1] + s[mid]) / 2.0

    # If no records, nothing to do
    if not records:
        return records

    # Extract numeric values, validating finiteness
    values = []
    try:
        for rec in records:
            v = rec['value']
            fv = float(v)
            if not math.isfinite(fv):
                # Non-finite value -> degenerate batch
                raise ValueError("non-finite value")
            values.append(fv)
    except Exception:
        # Degenerate batch: set outlier = False for all and return
        for rec in records:
            rec['outlier'] = False
        return records

    # Compute median
    try:
        med = _median(values)
        if not math.isfinite(med):
            raise ValueError("non-finite median")
    except Exception:
        for rec in records:
            rec['outlier'] = False
        return records

    # Compute MAD
    deviations = [abs(v - med) for v in values]
    try:
        mad = _median(deviations)
        if not math.isfinite(mad):
            raise ValueError("non-finite MAD")
    except Exception:
        for rec in records:
            rec['outlier'] = False
        return records

    # Determine scale: prefer MAD; if MAD == 0, fall back to population std dev
    scale = mad
    if mad == 0:
        # Compute population standard deviation
        n = len(values)
        if n == 0:
            for rec in records:
                rec['outlier'] = False
            return records
        mean = sum(values) / n
        # variance
        var = sum((v - mean) ** 2 for v in values) / n
        if not math.isfinite(var):
            for rec in records:
                rec['outlier'] = False
            return records
        std = math.sqrt(var)
        if not math.isfinite(std):
            for rec in records:
                rec['outlier'] = False
            return records
        scale = std

    # If scale is zero (degenerate spread), no outliers
    if scale == 0:
        for rec in records:
            rec['outlier'] = False
        return records

    threshold = 3 * scale

    # Mark outliers
    for rec, v in zip(records, values):
        rec['outlier'] = abs(v - med) > threshold

    return records

