    Merge integer intervals from input records, then pass through the original records.

    Each input record is a dict with integer 'start' and 'end' (start <= end).
    Overlapping intervals and intervals that touch (end == next.start) are merged.
    Returns a list where:
      - first come the merged intervals as dicts with only 'start' and 'end', sorted by start;
      - then the original input records (unchanged) are appended in their original order.
    """
    # Extract intervals as tuples to avoid mutating input and to sort easily
    intervals = [(r['start'], r['end']) for r in records]
    # If no records, return the original (empty) list
    if not intervals:
        return list(records)

    # Sort by start ascending (and by end as tie-breaker for determinism)
    intervals.sort(key=lambda x: (x[0], x[1]))

    merged = []
    cur_start, cur_end = intervals[0]
    for s, e in intervals[1:]:
        # If next interval overlaps or touches (s <= cur_end), merge
        if s <= cur_end:
            if e > cur_end:
                cur_end = e
        else:
            merged.append({'start': cur_start, 'end': cur_end})
            cur_start, cur_end = s, e

    # Append the last merged interval
    merged.append({'start': cur_start, 'end': cur_end})

    # Return merged intervals followed by the original records
    return merged + list(records)

